import type { Request, Response } from "express";
import { db } from "../../database/db.js";
import { riskTop5Mitigations } from "../../schema/risks/riskTop5Mitigations.js";
import { getTop5RisksWithMitigations } from "../../services/getTop5RisksFromAssessmentContext.js";

/**
 * POST /buyerCotsAssessment/autoGenerated
 * Auto-Generated section per AI EVAL Database Fields Reference (Buyer Side CSV).
 * Returns values aligned with Notes: risk linkage, domain-level scoring, context adjustments, mitigation tactics.
 *
 * Contextual multipliers Intent comes from AI Risk Intellect when the Controls API key
 * is set (extra step after AI-Q risk DB match); otherwise falls back to local/default.
 */
const getBuyerCotsAutoGenerated = async (req: Request, res: Response) => {
  try {
    const body = req.body ?? {};
    const _formData = {
      businessPainPoint: body.businessPainPoint ?? body.business_pain_point,
      vendorName: body.vendorName ?? body.vendor_name,
      dataSensitivity: body.dataSensitivity ?? body.data_sensitivity,
      regulatoryRequirements: body.regulatoryRequirements ?? body.regulatory_requirements,
      riskAppetite: body.riskAppetite ?? body.risk_appetite,
    };

    // Per-assessment top-5 (risk-mapping v2). Single source for identified risks, domain scores,
    // and intent — NOT the catalogue-wide risks table (which was identical for every assessment).
    let top5: Awaited<ReturnType<typeof getTop5RisksWithMitigations>> | null = null;
    try {
      top5 = await getTop5RisksWithMitigations({
        productName: body.productName ?? body.product_name ?? _formData.vendorName,
        industry_sector: body.industrySector ?? body.industry_sector,
        industry: body.industry,
        customer_sector: body.customerSector ?? body.customer_sector,
        dataSensitivity: _formData.dataSensitivity,
        regulatoryRequirements: _formData.regulatoryRequirements,
        impactedStakeholders: body.impactedStakeholders ?? body.impacted_stakeholders,
        decisionStakes: body.decisionStakes ?? body.decision_stakes,
        productFeatures: body.productFeatures ?? body.product_features,
        useCaseTypes: body.useCaseTypes ?? body.use_case_types,
        business_pain_point: _formData.businessPainPoint,
        expected_outcomes: body.expectedOutcomes ?? body.expected_outcomes,
        // Validated inside getTop5RisksWithMitigations — only real risk_mapping_ids are honoured.
        risk_mitigation_mapping_ids:
          body.riskMitigationMappingIds ?? body.risk_mitigation_mapping_ids,
      });
    } catch (e) {
      console.error("autoGenerated top-5 selection failed:", e);
    }
    const top5Risks = top5?.top5Risks ?? [];

    // 1) Identified Risks – now the per-assessment top-5 (risk id + title), not the full risks table.
    const identifiedRisks =
      top5Risks.length === 0
        ? "Not enough assessment detail to select risks."
        : top5Risks.map((r) => `${r.risk_id}: ${r.risk_title ?? ""}`).join("\n");

    // 2) Risk Domain Scores – per-assessment domain counts from the top-5 (not catalogue-wide counts).
    // NOTE: feeds the buyer readiness score + MyVendors severity; this is a deliberate INPUT change
    // (scoring formulas/weights are unchanged). Needs Asad sign-off before any production re-score.
    const domainCounts = top5Risks.reduce<Record<string, number>>((acc, r) => {
      const domain = r.domains ?? "Other";
      acc[domain] = (acc[domain] ?? 0) + 1;
      return acc;
    }, {});
    const riskDomainScores =
      Object.keys(domainCounts).length === 0
        ? "Not enough assessment detail to select risks."
        : Object.entries(domainCounts)
            .map(([domain, count]) => `${domain}: ${count}`)
            .join(", ");

    // 3) Contextual Multipliers – Intent from the same top-5 (AI Risk Intellect when API key is set).
    const contextualMultipliers = top5?.intentScore?.label
      ? `${top5.intentScore.label}, Timing: Pre-deployment`
      : "Intent: Mixed (1.0), Timing: Pre-deployment (contextual multipliers can be extended when rules are defined).";

    // 4) Buyer Risk Mitigation – display text unchanged. Mitigation-ID passthrough REMOVED: this
    // endpoint no longer returns mitigation mapping_ids (they were mis-used as risk_mapping PKs).
    const mitigationsRows = await db.select().from(riskTop5Mitigations);
    const riskMitigationMappingIds: number[] = [];
    const riskMitigation =
      mitigationsRows.length === 0
        ? "No risk mitigations defined in the system yet."
        : mitigationsRows
            .map((m) => {
              const parts = [`[${m.risk_id}] ${m.mitigation_action_name} (${m.mitigation_category})`];
              if (m.mitigation_definition) parts.push(` – ${m.mitigation_definition}`);
              return parts.join("");
            })
            .join("\n\n");

    return res.status(200).json({
      data: {
        identifiedRisks,
        riskDomainScores,
        contextualMultipliers,
        riskMitigation,
        riskMitigationMappingIds,
      },
    });
  } catch (error) {
    console.error(
      "Error in getBuyerCotsAutoGenerated:",
      error instanceof Error ? error.message : String(error)
    );
    return res.status(500).json({ message: "Internal server error" });
  }
};

export default getBuyerCotsAutoGenerated;
